('0bb7ba83-35b6-4b6f-bf4c-18da76798209'::uuid,'IMAGE','https://commons.wikimedia.org/wiki/Special:Redirect/file/Hakk%C3%A2ri%20Cilo%20and%20Sat%20Mountains%20jully%202023.jpg?width=1600','https://commons.wikimedia.org/wiki/File:Hakk%C3%A2ri_Cilo_and_Sat_Mountains_jully_2023.jpg','Wikimedia Commons','CC BY-SA 4.0','Arcmem / Wikimedia Commons','Cilo ve Sat Dağları yaz mevsimi panoraması',2,false,true,'{"sourceVerified":true,"location":"Cilo ve Sat Dağları, Hakkari"}'::jsonb),
