('c457b08f-4d10-44fd-97e8-8c0fe7194564'::uuid,'IMAGE','https://commons.wikimedia.org/wiki/Special:Redirect/file/Zap%20Nehri...%20-%20panoramio.jpg?width=1600','https://commons.wikimedia.org/wiki/File:Zap_Nehri..._-_panoramio.jpg','Wikimedia Commons','CC BY-SA 3.0','hamza atılgan / Wikimedia Commons','Zap Nehri Hakkari doğa görünümü',2,false,true,'{"sourceVerified":true,"location":"Zap Nehri, Hakkari"}'::jsonb)
) as v(tour_id,kind,external_url,source_url,source_name,license,attribution,alt_text,sort_order,is_cover,is_active,metadata)
